const q = $input.first().json.query || {};
const expected = 'REPLACE_META_VERIFY_TOKEN';
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === expected;
return [{ json: { statusCode: ok ? 200 : 403, body: ok ? String(q['hub.challenge'] || '') : 'verification_failed' } }];

const body = $input.first().json.body || {};
const out = [];
const objectType = String(body.object || '').toLowerCase();
const sourceChannel = objectType.includes('instagram') ? 'instagram' : 'facebook';
for (const entry of body.entry || []) {
  for (const ev of entry.messaging || []) {
    const text = ev.message?.text || ev.postback?.payload || '';
    if (!text) continue;
    out.push({ json: {
      clinic_id: 'REPLACE_CLINIC_ID',
      source_channel: sourceChannel,
      source_user_id: ev.sender?.id || '',
      message_text: text,
      message_timestamp: ev.timestamp ? new Date(ev.timestamp).toISOString() : new Date().toISOString(),
      reply_mode: 'meta',
      raw_payload: body
    }});
  }
}
return out;

const body = $input.first().json.body || $input.first().json || {};
const sourceChannel = body.source_channel || body.channel || 'website';
const userId = body.source_user_id || body.sender_id || body.user_id || body.email || body.mobile_number || `anon-${Date.now()}`;
return [{ json: {
  clinic_id: body.clinic_id || 'REPLACE_CLINIC_ID',
  source_channel: sourceChannel,
  source_user_id: String(userId),
  client_name: body.client_name || body.name || null,
  mobile_number: body.mobile_number || body.phone || null,
  message_text: body.message_text || body.text || body.message || '',
  message_timestamp: body.message_timestamp || new Date().toISOString(),
  reply_mode: 'webhook',
  raw_payload: body
}}];

// Deterministic language detection, so the agent is TOLD the language rather than asked to
// notice it. Live testing showed it mirroring Taglish in one conversation and answering the
// same Taglish opener in English in another. Words that are also English ("at", "na", "sa")
// are deliberately left out, and two DISTINCT markers are required, so one loanword in an
// otherwise English sentence does not flip the whole reply into Taglish.
const TAGALOG_MARKERS = /\b(po|opo|ako|ikaw|kayo|namin|natin|ninyo|niya|nila|ang|ng|mga|ay|kung|kasi|pero|yung|yun|ito|iyan|ba|naman|lang|sige|salamat|magkano|ano|sino|saan|kailan|paano|bakit|gusto|pwede|puwede|meron|mayroon|wala|hindi|bukas|ngayon|mamaya|kumusta|kamusta|maganda|magandang|pasensya|tulong|araw|ngipin|bunot|pabunot|sakit|masakit)\b/g;

return $input.all().map(item => {
  const j = item.json;
  const markerHits = new Set((String(j.message_text || '').toLowerCase().match(TAGALOG_MARKERS) || []));
  const patientLanguage = markerHits.size >= 2 ? 'Taglish' : 'English';
  const conversationId = j.conversation_id || `${j.clinic_id}:${j.source_channel}:${j.source_user_id}`;
  return { json: {
    ...j,
    conversation_id: conversationId,
    lead_id: j.lead_id || conversationId,
    message_text: String(j.message_text || '').trim(),
    received_at: new Date().toISOString(),
    clinic_timezone: 'Asia/Manila',
    patient_language: patientLanguage,
    // Clinic profile. THIS IS THE ONLY PLACE YOU EDIT to point the front desk at your
    // own practice. Single source of truth for hours: Check Hours, Check Move Hours,
    // Build Reject Reply and the agent's Context block all read these and nothing else.
    // See config/clinic.example.json and docs/SOP_CUSTOMIZE.md.
    clinic_name: 'Example Dental Clinic',
    clinic_open_hour: 8,               // 24h clock. 8 = 8AM. First bookable hour.
    clinic_close_hour: 17,             // 24h clock. 17 = 5PM. Last appointment ENDS by this hour.
    clinic_closed_weekdays: [7],       // ISO weekdays, 1=Mon ... 7=Sun. [7] = closed Sundays.
    clinic_hours_text: 'Monday to Saturday, 8AM to 5PM, closed Sunday',
    clinic_address: '123 Example Street, Your City',
    clinic_mobile: '000 000 0000',
    clinic_email: 'hello@example-dental.test',
    clinic_dentist: 'Dr. Example Dentist',
    clinic_last_walk_in: '4:30PM'      // Latest a walk-in is accepted. Text only, shown to patients.
  }};
}).filter(item => item.json.message_text);

// Canonical PH mobile: 09 + 9 digits. '+63 9' + 9 digits resolves to the same number.
function normalizePH(raw) {
  if (raw === null || raw === undefined) return { value: null, valid: false, given: false };
  const given = String(raw).trim();
  if (!given) return { value: null, valid: false, given: false };
  let n = given.replace(/[^\d+]/g, '');
  if (n.startsWith('+63')) n = '0' + n.slice(3);
  else if (n.startsWith('63') && n.length === 12) n = '0' + n.slice(2);
  else if (n.startsWith('9') && n.length === 10) n = '0' + n;
  n = n.replace(/\D/g, '');
  const valid = /^09\d{9}$/.test(n);
  return { value: valid ? n : given, valid, given: true };
}

// Age arrives as free text ("34", "34 years old"). Keep the digits, sanity check
// the range, and hand a clean string to the sheet.
function normalizeAge(raw) {
  if (raw === null || raw === undefined) return { value: null, valid: false, given: false };
  const given = String(raw).trim();
  if (!given) return { value: null, valid: false, given: false };
  const m = given.match(/\d{1,3}/);
  if (!m) return { value: given, valid: false, given: true };
  const n = parseInt(m[0], 10);
  const valid = n >= 0 && n <= 120;
  return { value: valid ? String(n) : given, valid, given: true };
}

// Prompt-only enforcement of the no-dash rule failed on every long reply during
// live testing: the knowledge base carries en dashes inside price ranges and the
// model adds em dashes of its own. Strip them here so the rule cannot be broken.
function stripDashes(raw) {
  if (raw === null || raw === undefined) return raw;
  return String(raw)
    // a dash opening a line is a bullet, keep it as one
    .replace(/^([ \t]*)[\u2014\u2013][ \t]*/gm, '$1- ')
    // en dash between numbers is a range: 1,000-2,000
    .replace(/(\d)\s*\u2013\s*(\d)/g, '$1-$2')
    // a dash joining two weekdays is a day range, not a clause break:
    // Monday - Friday. Without this the catch-all below turned clinic hours
    // into 'Monday, Friday', which misstates the schedule to a patient.
    .replace(/\b((?:Mon|Tues|Tue|Wednes|Wed|Thurs|Thur|Thu|Fri|Satur|Sat|Sun)(?:day)?)\s*[\u2014\u2013]\s*((?:Mon|Tues|Tue|Wednes|Wed|Thurs|Thur|Thu|Fri|Satur|Sat|Sun)(?:day)?)\b/gi, '$1-$2')
    // a dash after AM/PM and before a number is a time range: 9:00 AM - 7:00 PM.
    // The numeric rule above misses these because the left side ends in a letter.
    .replace(/([AaPp]\.?[Mm]\.?)\s*[\u2014\u2013]\s*(\d)/g, '$1-$2')
    // anything else reads as a clause break, which a comma handles
    .replace(/\s*[\u2014\u2013]\s*/g, ', ');
}

// Live chat showed replies arriving JSON-encoded: wrapped in quotes, with line
// breaks as the two characters backslash-n. The prompt says not to, but the
// model does it anyway on long replies, so undo the encoding here.
function decodeEscapedText(raw) {
  if (raw === null || raw === undefined) return raw;
  let s = String(raw)
    .replace(/\\r\\n/g, '\n')
    .replace(/\\[rn]/g, '\n')
    .replace(/\\t/g, ' ')
    .replace(/\\"/g, '"');
  // a quote pair wrapping the WHOLE reply is the model quoting itself, not
  // punctuation, so drop it. Nested twice at most.
  for (let i = 0; i < 2; i++) {
    const t = s.trim();
    if (t.length > 1 && /^["\u201C]/.test(t) && /["\u201D]$/.test(t)) s = t.slice(1, -1);
    else break;
  }
  return s.trim();
}

// Literal bullet characters are not markdown, so a run of them renders as one collapsed
// line. Live testing produced exactly that for the 14 item services list. Rewrite them as
// hyphen bullets and make sure a list is separated from the paragraph above it.
// Deliberately narrow: it only touches lines that ALREADY open with a bullet character. A
// broader rule here is how stripDashes once turned "Monday-Friday" into "Monday, Friday".
function normalizeLists(raw) {
  if (raw === null || raw === undefined) return raw;
  const lines = String(raw).split('\n');
  const out = [];
  for (const original of lines) {
    const line = original.replace(/^([ \t]*)[\u2022\u25CF\u25AA\u25E6\u2023\u00B7]+[ \t]*/, '$1- ');
    const isItem = /^[ \t]*- /.test(line);
    const prev = out.length ? out[out.length - 1] : '';
    if (isItem && prev.trim() !== '' && !/^[ \t]*- /.test(prev)) out.push('');
    out.push(line);
  }
  return out.join('\n');
}

function cleanText(raw) {
  const decoded = decodeEscapedText(raw);
  if (decoded === null || decoded === undefined) return decoded;
  return normalizeLists(stripDashes(decoded));
}

const base = $json.base || {};
const decision = $json.decision || {};
const mob = normalizePH(decision.mobile_number || base.mobile_number);
const age = normalizeAge(decision.age || base.age);
const merged = {
  ...base,
  reply_text: cleanText(decision.reply_text) || 'Thanks. The clinic team will confirm this for you.',
  action: decision.action || 'answer',
  inquiry_type: decision.inquiry_type || 'other',
  client_name: decision.client_name || base.client_name || null,
  mobile_number: mob.value,
  mobile_valid: mob.valid,
  mobile_given: mob.given,
  age: age.value,
  age_valid: age.valid,
  age_given: age.given,
  service_or_concern: decision.service_or_concern || null,
  booking_status: decision.booking_status || 'none',
  patient_confirmed: decision.patient_confirmed === true,
  appointment_start: decision.appointment_start || null,
  appointment_end: decision.appointment_end || null,
  calendar_event_id: decision.calendar_event_id || null,
  handoff_reason: decision.handoff_reason || null,
  staff_review_required: Boolean(decision.staff_review_required),
  conversation_summary: cleanText(decision.conversation_summary) || '',
  human_task_required: Boolean(
    decision.human_task_required || decision.action === 'handoff' || decision.staff_review_required
  ),
  human_task_type: decision.human_task_type || null,
  human_task_note: decision.human_task_note || null,
  staff_email_required: Boolean(
    decision.staff_email_required || decision.action === 'handoff' || decision.staff_review_required
  ),
  staff_email_subject: decision.staff_email_subject || `AI front desk: ${decision.action || 'update'}`,
  staff_email_body: cleanText(decision.staff_email_body || decision.conversation_summary || decision.reply_text) || '',
  processed_at: new Date().toISOString()
};
return [{ json: merged }];

const original = $json.booking || {};
const event = $json.event || {};
const start = original.appointment_start;
const serviceRaw = original.service_or_concern || 'your appointment';
// this opens a sentence in the booking confirmation, which is the most screenshotted
// message the clinic sends, so it should not start lowercase
const service = serviceRaw.charAt(0).toUpperCase() + serviceRaw.slice(1);
let when = start;
try { const d = DateTime.fromISO(start).setZone('Asia/Manila'); if (d.isValid) when = d.toFormat('cccc, MMM d') + ' at ' + d.toFormat('h:mm a'); } catch (e) {}
const reply = `You're all booked!\n\n${service} on ${when}.\n\nIf you ever need to reschedule or cancel, just message me here. See you soon!`;
return [{ json: {
  ...original,
  calendar_event_id: event.id || event.htmlLink || original.calendar_event_id || null,
  booking_status: 'confirmed',
  action: 'book',
  reply_text: reply,
  human_task_required: false,
  human_task_type: null,
  human_task_note: null,
  staff_email_required: false,
  staff_email_subject: null,
  staff_email_body: null
}}];

// Bookings is matched on Event ID, which Google Calendar assigns per
// appointment and keeps stable across reschedules. Matching on Phone instead
// would merge two people who share a number (a family) into a single row.
//
// Any key we leave out is left untouched on the existing row, so unknown
// values are omitted rather than written as blanks that would erase good data.
const j = $json;
let appt = null;
if (j.appointment_start) {
  const d = DateTime.fromISO(j.appointment_start).setZone('Asia/Manila');
  if (d.isValid) appt = d.toFormat('ccc MMM d, h:mm a');
}
const row = {
  'Event ID': j.calendar_event_id || null,
  'Appointment': appt,
  // The name is captured properly at booking time. Reschedule and cancel turns
  // often carry a degraded version of it (Maria Cruz -> Marian -> Maria), so
  // they must never rewrite it.
  'Patient': j.action === 'book' ? (j.client_name || null) : null,
  // Age travels with the name, for the same reason: only the booking turn is
  // trusted to set it.
  'Age': j.action === 'book' ? (j.age || null) : null,
  'Service': j.service_or_concern || null,
  'Phone': j.mobile_number || null,
  'Status': j.booking_row_status || 'Confirmed',
  'Notes': j.booking_row_notes || null
};
const out = {};
for (const k in row) {
  if (row[k] !== null && row[k] !== undefined && row[k] !== '') out[k] = row[k];
}
return [{ json: out }];

