={{ (() => {
  const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const toks = (s) => norm(s).split(' ').filter(Boolean);
  let dec = {};
  try { dec = $('Parse Agent Decision').item.json || {}; } catch (e) { dec = {}; }
  let events = [];
  try { events = $('Find Appointment').all().map((i) => i.json).filter((e) => e && e.id); } catch (e) { events = []; }
  if (!events.length) return { matched: false, match_reason: 'no-upcoming-events' };
  const nameOf = (ev) => { const parts = String(ev.summary == null ? '' : ev.summary).split(' - '); return parts.length > 1 ? parts[1] : String(ev.summary == null ? '' : ev.summary); };
  const names = events.map(nameOf);
  const want = toks(dec.client_name);
  if (!want.length) {
    if (events.length === 1) return Object.assign({}, events[0], { matched: true, match_reason: 'mobile-only', candidates: 1 });
    return { matched: false, match_reason: 'ambiguous-no-name', candidates: events.length, candidate_names: names.join(' | ') };
  }
  const exact = events.filter((ev) => norm(nameOf(ev)) === norm(dec.client_name));
  const partial = events.filter((ev) => {
    const have = toks(nameOf(ev));
    if (!have.length) return false;
    return want.every((t) => have.includes(t)) || have.every((t) => want.includes(t));
  });
  const pool = exact.length ? exact : partial;
  if (!pool.length) return { matched: false, match_reason: 'name-mismatch', candidates: events.length, candidate_names: names.join(' | ') };
  if (pool.length > 1) return { matched: false, match_reason: 'ambiguous-name', candidates: pool.length, candidate_names: pool.map(nameOf).join(' | ') };
  return Object.assign({}, pool[0], { matched: true, match_reason: exact.length ? 'exact' : 'partial', candidates: events.length });
})() }}

